#!/usr/bin/env python3
"""Original, editable anatomy drawings. All visible artwork is native SVG geometry."""
from pathlib import Path
from html import escape
import json, random

ROOT=Path(__file__).resolve().parents[1]
INK='#24343b'; PAPER='#f3eee2'
serial=0
def path(d,fill='none',stroke=INK,w=2,opacity=1,extra=''):
    return f'<path d="{d}" fill="{fill}" stroke="{stroke}" stroke-width="{w}" opacity="{opacity}" stroke-linecap="round" stroke-linejoin="round" {extra}/>'
def lines(ds,w=1.8,opacity=.65,color=INK):
    return ''.join(path(d,stroke=color,w=w,opacity=opacity) for d in ds)
def ink(d,fill='url(#body)',w=3.1): return path(d,fill,w=w)
def light(d,opacity=.7): return path(d,'url(#light)','none',0,opacity)
def hatch(d,bounds,opacity=.38,step=8):
    global serial
    serial+=1;c=f'hatch-{serial}'; x,y,w,h=bounds
    s=f'<defs><clipPath id="{c}"><path d="{d}"/></clipPath></defs><g clip-path="url(#{c})" opacity="{opacity}" stroke="{INK}" fill="none" stroke-width=".85">'
    for a in range(int(x-h),int(x+w+h),step):
        s+=f'<path d="M{a} {y} Q{a+h*.38} {y+h*.48} {a+h*.82} {y+h}"/>'
    s+='</g>'
    return s
def shade(d,bounds,opacity=.75):
    return path(d,'url(#shadow)','none',0,opacity)+hatch(d,bounds,.42)
def flow(ds):
    global serial
    serial+=1
    return f'<g id="anatomical-flow-{serial}" opacity="0">'+lines(ds,2.3,.68,'#a66a42')+'@@FLOW@@</g>'
def moving(name,body,values,pivot):
    x,y=pivot
    return f'<g id="{name}">{body}@@ROT:{values}:{x}:{y}@@</g>'
def base_defs():
    return '''<defs>
<radialGradient id="paper"><stop stop-color="#fbf8f0"/><stop offset="1" stop-color="#eee6d6"/></radialGradient>
<linearGradient id="body" x1=".13" y1=".12" x2=".89" y2=".81" gradientUnits="objectBoundingBox"><stop stop-color="#fffaf0"/><stop offset=".32" stop-color="#e8dfcb"/><stop offset=".64" stop-color="#b6b8aa"/><stop offset=".87" stop-color="#697a78"/><stop offset="1" stop-color="#41545a"/></linearGradient>
<linearGradient id="body2" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#ece4d2"/><stop offset=".55" stop-color="#b9b9a8"/><stop offset="1" stop-color="#506568"/></linearGradient>
<linearGradient id="shadow" x1="0" y1="0" x2="1" y2=".55"><stop stop-color="#5d716f" stop-opacity=".05"/><stop offset=".56" stop-color="#3f5659" stop-opacity=".55"/><stop offset="1" stop-color="#24343b" stop-opacity=".94"/></linearGradient>
<linearGradient id="light" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fffdf5" stop-opacity=".98"/><stop offset="1" stop-color="#fff9e8" stop-opacity=".05"/></linearGradient>
<linearGradient id="forefoot-tone" gradientUnits="userSpaceOnUse" x1="448" y1="336" x2="811" y2="655"><stop stop-color="#fffaf0"/><stop offset=".36" stop-color="#dddaca"/><stop offset=".73" stop-color="#9ca99f"/><stop offset="1" stop-color="#5b7072"/></linearGradient>
<linearGradient id="foot-tone" gradientUnits="userSpaceOnUse" x1="427" y1="400" x2="812" y2="645"><stop stop-color="#eee5d2"/><stop offset=".43" stop-color="#c7c9b9"/><stop offset="1" stop-color="#526a6b"/></linearGradient>
<radialGradient id="ground"><stop stop-color="#293b3f" stop-opacity=".15"/><stop offset="1" stop-color="#293b3f" stop-opacity="0"/></radialGradient>
</defs>'''
def atmosphere():
    rng=random.Random(37)
    out='<rect width="1200" height="900" fill="#f3eee2"/><rect x="25" y="25" width="1150" height="850" fill="url(#paper)" opacity=".7"/><g id="paper-grain" fill="#665f50" opacity=".10">'
    for _ in range(550):
        x=rng.randrange(80,1120);y=rng.randrange(70,820);r=rng.choice([.35,.45,.6])
        out+=f'<circle cx="{x}" cy="{y}" r="{r}"/>'
    return out+'</g>'
def plate(num,title,body,animated=False):
    import re
    if animated:
        body=body.replace('@@FLOW@@','<animate attributeName="opacity" values="0;0;.85;.85;0;0" keyTimes="0;.13;.39;.56;.83;1" dur="7s" repeatCount="indefinite" calcMode="spline" keySplines=".42 0 .58 1;.42 0 .58 1;.42 0 .58 1;.42 0 .58 1;.42 0 .58 1"/>')
        def rot(m):
            vals=m[1].split(','); x=m[2];y=m[3]
            return f'<animateTransform attributeName="transform" type="rotate" values="'+ ';'.join(f'{v} {x} {y}' for v in vals)+'" keyTimes="0;.14;.43;.61;.85;1" dur="7s" repeatCount="indefinite" calcMode="spline" keySplines=".42 0 .58 1;.22 .6 .35 1;.42 0 .58 1;.42 0 .58 1;.42 0 .58 1"/>'
        body=re.sub(r'@@ROT:([^:]+):([^:]+):([^@]+)@@',rot,body)
    else:
        body=body.replace('@@FLOW@@','')
        body=re.sub(r'@@ROT:[^@]+@@','',body)
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="900" viewBox="0 0 1200 900" role="img" aria-labelledby="title desc">
<title id="title">{escape(title)}</title><desc id="desc">Original graphite, indigo and warm ivory anatomical drawing inspired by the form study in source photograph {num}.jpg. Native editable vector contours, tonal planes and crosshatching. {'Seven-second seamless anatomical study animation.' if animated else 'Static corpus illustration.'} An artistic study, not a clinical reference.</desc>
{base_defs()}{atmosphere()}<g id="original-anatomical-illustration">{body}</g></svg>'''

