def finger(name,base,tip,width,bend=0,nail=True):
    """A tapered curved digit, local axis points upward; separate joint folds."""
    x,y=base;tx,ty=tip;w=width; dx=tx-x
    d=f'M{x-w*.5} {y} C{x-w*.57} {y-45} {tx-w*.56} {ty+82} {tx-w*.48} {ty+25} C{tx-w*.4} {ty-5} {tx+w*.39} {ty-12} {tx+w*.49} {ty+20} C{tx+w*.61} {ty+69} {x+w*.61} {y-38} {x+w*.48} {y}Z'
    s=ink(d,w=2.5)
    sh=f'M{tx+w*.20} {ty+15} C{tx+w*.48} {ty+80} {x+w*.5} {y-50} {x+w*.48} {y} L{x+w*.05} {y} C{x+w*.21} {y-60} {tx+w*.2} {ty+87} {tx+w*.20} {ty+15}Z'
    s+=shade(sh,(min(x,tx)-w/2,ty,w+abs(dx),y-ty),.75)
    if nail:
        s+=path(f'M{tx-w*.27} {ty+33} C{tx-w*.29} {ty+12} {tx+w*.27} {ty+10} {tx+w*.29} {ty+32} L{tx+w*.27} {ty+57} Q{tx} {ty+66} {tx-w*.26} {ty+57} Z','url(#light)',INK,1.15,.8)
    for ratio in [.40,.70]:
        jy=ty+(y-ty)*ratio;jx=tx+(x-tx)*ratio
        s+=lines([f'M{jx-w*.39} {jy} Q{jx} {jy-8} {jx+w*.35} {jy-2}',f'M{jx-w*.27} {jy+6} Q{jx} {jy} {jx+w*.25} {jy+5}'],1.25,.7)
    return moving(name,s,f'0,{-bend*.2},{bend},{bend*.8},{-bend*.1},0',(x,y))

